package com.example.contor.ai.eval;

import tools.jackson.databind.DeserializationFeature;
import tools.jackson.databind.ObjectMapper;
import tools.jackson.databind.json.JsonMapper;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.net.URISyntaxException;
import java.net.URL;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.LocalDate;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Stream;

/**
 * The business mailbox and its expectations, generated by {@code scripts/business-dataset/build.mjs} from the committed
 * storylines: messages in time order, the expected end state of every collection after the whole mailbox, and the
 * insights a good insight pass finds.
 */
final class BusinessCorpus {

    static final String ROOT = "ai-eval/business";
    static final String MAILBOX = ROOT + "/mailbox";
    private static final ObjectMapper MAPPER = JsonMapper.builder().disable(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES).build();

    private BusinessCorpus() {
    }

    /** What the collections hold after the mailbox; {@code sources} are the messages each record was labelled in. */
    record EndState(String asOf, Map<String, List<StateRecord>> records, List<StateRelation> relations) {

        EndState {
            records = records != null ? records : Map.of();
            relations = relations != null ? relations : List.of();
        }
    }

    record StateRecord(String title, Map<String, Object> values, List<String> sources) {

        StateRecord {
            values = values != null ? values : Map.of();
            sources = sources != null ? sources : List.of();
        }
    }

    record StateRelation(String type, String from, String to, List<String> sources) {
    }

    /** An insight that is fair to expect from {@code asOf} on, citing (at least) the {@code evidence} messages. */
    record ExpectedInsight(String id, String storyline, String title, LocalDate asOf, List<String> evidence) {
    }

    private record Insights(List<ExpectedInsight> insights) {
    }

    static List<BusinessMessage> messages() {
        try (Stream<Path> files = Files.list(resource(MAILBOX))) {
            return files.filter(file -> file.toString().endsWith(".json")).map(file -> read(file, BusinessMessage.class))
                    .sorted(Comparator.comparing((BusinessMessage message) -> message.email().receivedAt()).thenComparing(BusinessMessage::id))
                    .toList();
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    static Map<String, BusinessMessage> byId(List<BusinessMessage> messages) {
        Map<String, BusinessMessage> byId = new LinkedHashMap<>();
        messages.forEach(message -> byId.put(message.id(), message));
        return byId;
    }

    static EndState endState() {
        return read(resource(ROOT + "/expected/end-state.json"), EndState.class);
    }

    static List<ExpectedInsight> insights() {
        return read(resource(ROOT + "/expected/insights.json"), Insights.class).insights();
    }

    private static <T> T read(Path file, Class<T> type) {
        try {
            return MAPPER.readValue(Files.readString(file), type);
        } catch (IOException | RuntimeException e) {
            throw new IllegalStateException("Cannot read " + file + ": " + e.getMessage(), e);
        }
    }

    private static Path resource(String name) {
        URL url = BusinessCorpus.class.getClassLoader().getResource(name);
        if (url == null) {
            throw new IllegalStateException("Not on the classpath: " + name + " (run node scripts/business-dataset/build.mjs)");
        }
        try {
            return Path.of(url.toURI());
        } catch (URISyntaxException e) {
            throw new IllegalStateException(e);
        }
    }
}
